// TH15 Stage 2 boss nonspell (Boss1). Source: st02bs.ecl.txt:50-112.
// Entry state from st02bs.ecl.txt::Boss:8-48: position (0,128), hurtbox 40x40,
// hitbox 48x48, moveLimit(0,128,280,64). timerReset/[53] interrupt = 2400 frames.
const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// Source etSprite(5,4) with anmSelect(3); TH15 type 5 -> modern slot 432 (TH15_BALL2), color 4.
const TH15_BALL2: int = 432;
const BULLET_COLOR: int = 4;

// Source C parameter of Boss1_at: +-0.08726646 rad = +-5 deg, expressed in BAM.
const ANGLE_STEP: int = 910;

// ---- moveRand(60,4,speed) helper -------------------------------------------
// Source 412 at Boss1:410/98. Limits come from context moveLimit(0,128,280,64):
// real x in [-140,140], y in [96,160]; direction inner zone x +-70, y 112..144.
// Speed envelope is linear (1-k/60); k=60 stops. The queue value 1.0f/0.2f is
// the start speed, not a quadratic interpolation mode.

sub arm_next_step(v: fx) {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = ((60 - k) as fx / 60fx) * v; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_angle(a: angle, v: fx) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step(v);
}

sub card_move_rand(v: fx) {
    // signed unit random * pi, as unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_angle(a as angle, v);
}

sub card_wait(frames: int, v: fx) {
    var i: int = 0;
    while i < frames {
        wait(1);
        arm_next_step(v);
        i = i + 1;
    }
}

// ---- Boss1_at (dependency, st02bs.ecl.txt:114-166) -------------------------
// delta = source C (+-5 deg). Fixed-direction full ring (etAim 3), one layer,
// speed 1.5+0.05i (E/N/H) or 1.5+0.035i (L), ring size 16+i (E/N/H) or 20+i (L),
// base angle -90deg + i*C (B is unused by the source helper), birth distance
// 128-8i with etOffset(0,-8) and the ANIM entry shift -4*velocity.
async sub boss1_at(delta: int) {
    var rank: int = global(GVAR_RANK);
    var n: int = 16;
    var inc: fx = 0.05fx;
    var volleys: int = 11;
    var vwait: int = 12;
    if rank == 1 { volleys = 22; vwait = 6; }
    if rank == 2 { volleys = 27; vwait = 6; }
    if rank == 3 { n = 20; inc = 0.035fx; volleys = 38; vwait = 7; }

    sh_reset(0);
    sh_sprite(0, TH15_BALL2, BULLET_COLOR);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_offset(0, 0fx, -8fx);

    var base: int = -16384;      // -pi/2
    var spd: fx = 1.5fx;
    var dist: fx = 128fx;
    var i: int = 0;
    while i < volleys {
        sh_count(0, n + i, 1);
        sh_speed(0, spd, 0fx);
        sh_angle(0, base as angle, 0deg);
        sh_dist(0, dist - 4fx * spd);
        sh_fire(0);
        dist = dist - 8fx;
        base = base + delta;
        spd = spd + inc;
        i = i + 1;
        wait(vwait);
    }
}

// ---- Boss1 main loop (entry, st02bs.ecl.txt:50-112) ------------------------
// wait(120), moveRand(60,4,speed), wait(80 E/N/H | 240 L), alternating the two
// async launches with C=-5deg and C=+5deg.
async sub source_enemy() {
    set_invuln(65535);
    set_hitbox(24fx);   // source setHitbox(48,48) circle: 48*0.5
    set_hurtbox(20fx);  // source setHurtbox(40,40) circle: 40*0.5

    var rank: int = global(GVAR_RANK);
    var mv: fx = 1fx;   // queue value 1.0f (E/N/H) / 0.2f (L)
    var idle: int = 80;
    if rank == 3 { mv = 0.2fx; idle = 240; }

    wait(60);
    loop {
        spawn boss1_at(-ANGLE_STEP);
        wait(120);
        card_move_rand(mv);
        card_wait(idle, mv);
        spawn boss1_at(ANGLE_STEP);
        wait(120);
        card_move_rand(mv);
        card_wait(idle, mv);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
